struct Bits{u8* cursor;unsigned used;unsigned get(unsigned count){require(count<=16);unsigned value=0;while(count--){value=(value<<1)|((*cursor>>(7-used))&1);if(++used==8){used=0;++cursor;}}return value;}int signedValue(unsigned count){if(!count)return 0;unsigned value=get(count);return value<(1u<<(count-1))?(int)value-(int)((1u<<count)-1):(int)value;}void align(){if(used){used=0;++cursor;}}};
unsigned symbol(Bits& bits,const THPHuffmanTab& table){unsigned code=0;for(unsigned length=1;length<=16;++length){code=(code<<1)|bits.get(1);if(table.maxCode[length]>=0&&code<=(unsigned)table.maxCode[length]){int index=(int)code+table.valPtr[length];require(index>=0&&(unsigned)index<table.numVij);return table.Vij[index];}}require(false);return 0;}
void block(THPFileInfo* info,unsigned component,Bits& bits,u8* output){THPComponent& c=info->components[component];require(c.DCTableSelector<2&&c.ACTableSelector<2&&c.quantizationTableSelector<3&&(info->validHuffmanTabs&(1<<(c.DCTableSelector*2)))&&(info->validHuffmanTabs&(1<<(c.ACTableSelector*2+1))));short coefficients[64]={0};unsigned n=symbol(bits,info->huffmanTabs[c.DCTableSelector*2]);require(n<=11);int prediction=c.predDC+bits.signedValue(n);require(prediction>=-32768&&prediction<=32767);coefficients[0]=c.predDC=(short)prediction;for(unsigned k=1;k<64;){unsigned code=symbol(bits,info->huffmanTabs[c.ACTableSelector*2+1]),run=code>>4,size=code&15;if(!size){if(run!=15)break;require(k+16<=64);k+=16;}else{k+=run;require(k<64&&size<=10);coefficients[zig[k++]]=(short)bits.signedValue(size);}}Melee360THPInverseBlock(coefficients,info->quantTabs[c.quantizationTableSelector],output);}
void packBlock(u8* destination,unsigned width,unsigned x,unsigned y,const u8* block){for(unsigned yy=0;yy<8;++yy)for(unsigned xx=0;xx<8;++xx){unsigned px=x+xx,py=y+yy;destination[(py/4)*(width/8)*32+(px/8)*32+(py%4)*8+px%8]=block[yy*8+xx];}}
